const D = { cell:.4, contrast:.55, energy:.6, speed:1, hue:220, ink:.85, angle:15, scale:1, density:.5, x:.5, y:.5, style:'newsprint', act:'print', seed:0 };
const P = Object.assign({}, D, (window.state.P && window.state.P.__SLOT__) || {});
const S = window.state.__SLOT__ || (window.state.__SLOT__ = {});
const K = window.state.clk || { t:0, cps:.5, beat:0, bar:0, cyc:0, phase:0, pulse:0, swell:0, section:0, intensity:.6, fps:60 };
const A = window.state.audio || { bass:0, lowmid:0, mid:0, treble:0, rms:0, fft:[] };

const md=(a,n)=>((a%n)+n)%n, frc=v=>v-Math.floor(v), clp=(v,a,b)=>Math.max(a,Math.min(b,v)), TAU=Math.PI*2;
const fr=i=>{const s=Math.sin(i*127.1+P.seed*311.7)*43758.5453;return s-Math.floor(s);};
const rgb2hsb=(r,g,b)=>{r/=255;g/=255;b/=255;const mx=Math.max(r,g,b),mn=Math.min(r,g,b),d=mx-mn;let h=0;if(d){if(mx===r)h=((g-b)/d)%6;else if(mx===g)h=(b-r)/d+2;else h=(r-g)/d+4;h*=60;if(h<0)h+=360;}return [h, mx?d/mx:0, mx];};
if(S.lastBeat==null||K.beat<S.lastBeat)S.lastBeat=K.beat; S.lastBeat=K.beat;

const W=width,Hh=height,u=Math.min(W,Hh);
const style=P.style;
const en=clp(P.energy,0,1)*(.5+.6*K.intensity);
const cellP=clp(P.cell,0,1), con=clp(P.contrast,0,1), inkA=clp(P.ink,0,1);
const eh=md(P.hue,360);
const led=style==='led', cmyk=style==='cmyk', duo=style==='duotone';

// act dramaturgy
let regE=1, sweepE=1;
if(P.act==='registration'){ regE=2.6; }
else if(P.act==='scan'){ sweepE=2.3; }

const cellPx=Math.max(4, u*(0.014+cellP*0.055));
const cols=clp(Math.round(W/cellPx),6,60), rows=clp(Math.round(Hh/cellPx),6,40);

// low-res sample of the composited frame below this post pass
if(!S.samp || S.sw!==cols || S.sh!==rows){ if(S.samp&&S.samp.remove)S.samp.remove(); S.samp=createGraphics(cols,rows); S.sw=cols; S.sh=rows; }
const samp=S.samp;
samp.clear();
samp.drawingContext.imageSmoothingEnabled=true;
try{ samp.drawingContext.drawImage(drawingContext.canvas,0,0,cols,rows); }catch(e){}
samp.loadPixels();
const px=samp.pixels;

const dc=drawingContext, oldOp=dc.globalCompositeOperation;

// paper / ground (re-render: cover the sampled frame, redraw it as dots)
noStroke();
if(led){ background(md(eh+200,360),35,7); }
else { background(md(eh+30,360),6,88); }

// global dot-size breathe = the reliable motion floor (non-8s period) + rms pump
const breathe = 0.86 + 0.13*Math.sin(K.t*0.5*(0.5+P.speed)) + K.swell*0.1 + A.rms*0.5 + K.pulse*0.07*en;
const cw=W/cols, chh=Hh/rows;
const maxR=Math.min(cw,chh)*0.72*breathe;
const ang0=md(P.angle,360)*TAU/360;

if(px && px.length>=cols*rows*4){
  if(led){ dc.globalCompositeOperation='lighter'; noStroke(); }
  else if(cmyk){ dc.globalCompositeOperation='multiply'; noStroke(); }
  else { noStroke(); }
  for(let j=0;j<rows;j++){
    for(let i=0;i<cols;i++){
      const idx=(j*cols+i)*4;
      const r=px[idx],g=px[idx+1],b=px[idx+2];
      let lum=(0.299*r+0.587*g+0.114*b)/255;
      lum=clp((lum-0.5)*(1+con*2.4)+0.5,0,1);
      const cx=(i+0.5)*cw, cy=(j+0.5)*chh;
      if(led){
        const bright=clp(lum,0,1)*breathe;
        if(bright>0.04){
          const hs=rgb2hsb(r,g,b);
          const hh=hs[1]>0.08? hs[0] : eh;
          const s=maxR*1.7*(0.35+0.65*bright);
          fill(hh, 40+hs[1]*55, 100, clp(55+40*bright,0,95)*inkA);
          rect(cx-s/2,cy-s/2,s,s);
        }
      } else if(cmyk){
        const R=r/255,G=g/255,B=b/255, k=1-Math.max(R,G,B), kd=(1-k)||1;
        const c=(1-R-k)/kd, m=(1-G-k)/kd, y=(1-B-k)/kd;
        const chans=[[c,180,80],[m,300,80],[y,55,85],[k,0,0]];
        for(let ci=0;ci<4;ci++){
          const cov=clp(chans[ci][0]*(0.55+con*0.9),0,1); if(cov<0.03)continue;
          const rr=maxR*0.95*Math.sqrt(cov);
          const reg=u*0.004*regE*(1+0.4*en);
          const ra=ci*TAU/4 + K.t*0.05*regE;
          fill(chans[ci][1], chans[ci][3], ci===3?12:95, 82*inkA);
          circle(cx+Math.cos(ra)*reg, cy+Math.sin(ra)*reg, rr*2);
        }
      } else {
        // newsprint + duotone: ink dot sized by darkness
        const dk=clp(1-lum,0,1);
        const rr=maxR*Math.sqrt(dk);
        if(rr>0.4){
          if(duo){ fill(md(eh,360), 55, 22, 92*inkA); }
          else { fill(md(eh,360), 10, 10, 92*inkA); }
          circle(cx,cy,rr*2);
        }
        if(duo && lum>0.55){ const rb=maxR*0.6*Math.sqrt(clp(lum-0.4,0,1)); fill(md(eh+40,360),60,95,55*inkA); circle(cx,cy,rb*2); }
      }
    }
  }
}
dc.globalCompositeOperation=oldOp;

// moving sheen band — second motion floor, sweeps in the screen-angle direction
const ux=Math.cos(ang0), uy=Math.sin(ang0);
const L=Math.abs(W*ux)+Math.abs(Hh*uy)+1;
const c=frc(K.t*0.05*sweepE*(0.4+P.speed))*L;
const bw=u*0.13;
const ox=W/2-(L/2-c)*ux, oy=Hh/2-(L/2-c)*uy;
dc.globalCompositeOperation='lighter';
const lg=dc.createLinearGradient(ox-bw*ux,oy-bw*uy,ox+bw*ux,oy+bw*uy);
lg.addColorStop(0,'rgba(255,255,255,0)');
lg.addColorStop(0.5,`rgba(255,255,255,${(0.05+0.09*en).toFixed(3)})`);
lg.addColorStop(1,'rgba(255,255,255,0)');
dc.fillStyle=lg; dc.fillRect(0,0,W,Hh);
dc.globalCompositeOperation=oldOp;

blendMode(BLEND); dc.globalCompositeOperation=oldOp; dc.shadowBlur=0; noStroke();
